  Context c=getTargetContext();LiveRestore live=new LiveRestore(c);BackupEngine e=live.engine;require(!OperationService.running()&&!ScheduledBackupService.running&&!live.pointer.exists(),"Operation or recovery active");require(!SetupCheck.installed(e),"Disposable app already present");require(!PasswordVault.remembered(c),"Existing saved password: do not overwrite");live.testing=true;
  SharedPreferences prefs=RestorePreferences.prefs(c);Map<String,?> original=prefs.getAll(),receipts=c.getSharedPreferences("archive-verification",0).getAll();char[] password="Raven disposable password 180".toCharArray();File job=e.job(),apk=new File(job,"helper.apk");Uri folder=null;List<String> paths=new ArrayList<>();boolean installed=false;
