   SetupCheck.mode(e,"mutate");Thread.sleep(250);boolean wrong=false;try{ArchiveAccess.unlock(c,encrypted,"wrong-password".toCharArray());}catch(Exception expected){wrong=true;}require(wrong,"Wrong password accepted");live.verifyLaunch(Collections.singletonList(SetupCheck.PACKAGE),true);ArchiveAccess.unlock(c,encrypted,password);Thread.sleep(250);
   LiveRestore.Plan restore=live.prepare(encrypted);String restored=live.restore(restore,false,false);require(restored.startsWith("Restored "),"Encrypted restore failed");live.verifyLaunch(Collections.singletonList(SetupCheck.PACKAGE),false);result.putString("encrypted_restore","PASS seekable encrypted app/APK/private/external backup, full verification, ownership/modes/labels and independent app launch/read; wrong password changed no app data");note("RESTORE_PASS");
   SetupCheck.mode(e,"mutate");live.restore(live.prepare(plain),false,false);live.verifyLaunch(Collections.singletonList(SetupCheck.PACKAGE),false);result.putString("plain_compatibility","PASS plaintext format-5 backup still restores after encrypted backup");
